@startuml

class Library {
  + Code : string
}

class User {
  + Name : string
  + ContactInfo : string
  + SecurityDeposit : float
}

class BorrowableItem {
  + LibraryCode : string
  + Location : string
}

class Book extends BorrowableItem {
  + Publisher : string
}

class Author {
  + Name : string
}

class MagazineIssue extends BorrowableItem {
  + PublicationDate : date
  + Publisher : string
}

class MusicCD extends BorrowableItem {
  + Publisher : string
  + Artist : string
}

class Film extends BorrowableItem {
  + Duration : int
  + Publisher : string
}

class VHSFilm extends BorrowableItem {}

class DVDFilm extends BorrowableItem {}

class Actor {
  + Name : string
}

class Loan {
  + ReturnDeadline : date
}

class ItemRequest {
  + RequestDate : date
}

Library "1" -- "*" User : has
Library "1" -- "*" BorrowableItem : has
Library "1" -- "*" ItemRequest : receives

User "0..1" -- "0..3" Loan : borrows
Loan "1" -- "1" BorrowableItem : involves

Book "1..*" -- "1..*" Author : written by
Film "1..*" -- "1..*" Actor : features

@enduml

